import{_ as r,o as t,c as a,a0 as n}from"./chunks/framework.ysVzM4be.js";const f=JSON.parse('{"title":"ADR 0002: Handoffs run through herdr","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0002-handoffs-run-through-herdr.md","filePath":"adr/0002-handoffs-run-through-herdr.md"}'),o={name:"adr/0002-handoffs-run-through-herdr.md"};function s(d,e,i,h,c,l){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0002-handoffs-run-through-herdr" tabindex="-1">ADR 0002: Handoffs run through herdr <a class="header-anchor" href="#adr-0002-handoffs-run-through-herdr" aria-label="Permalink to &quot;ADR 0002: Handoffs run through herdr&quot;">​</a></h1><p>Status: accepted Date: 2026-08-30</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>A handoff must start an interactive agent (pi, codex, claude code, or others). Agents are terminal UIs and need their own terminal, but the control plane is itself a terminal UI. The control plane will also need agent state later for the <code>running</code> and <code>done</code> ticket states.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>herdr is the only host for agent processes. The control plane never starts an agent process itself. It drives herdr through its CLI (child process, JSON output) for every environment kind: a live worktree is a herdr workspace at the existing checkout with a fresh tab, a worktree is a herdr-created git worktree, and a container is a reserved future kind.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li>Start processes directly for the live worktree kind, and use herdr only for worktrees. Rejected: two execution paths, two sets of spawn/readiness/prompt/observe code, and no terminal for an interactive agent in the control plane&#39;s own screen.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>herdr is a hard runtime dependency of the control plane.</li><li>The agent-agnostic seam stays in the control plane: agent types are config entries, and herdr&#39;s agent kind is one field among them.</li></ul>',10)])])}const p=r(o,[["render",s]]);export{f as __pageData,p as default};
